import commandSources from "./command-sources.json";

// Generated by scripts/sync-commands.ts from the sidebar links:
// page name (e.g. "cast-tempo-zone-earn") -> MDX file relative to
// commands/src/pages/reference/cast (e.g. "tempo/zone/earn.mdx").
const sources: Record<string, string> = commandSources;

export function getCommandSourceFile(pagePath: string): string | undefined {
  const pageName = pagePath.replace(/\.(mdx?)$/, "");
  return sources[pageName];
}
